const resposta = $input.first().json;

const conteudo = resposta.choices[0].message.content;

let classificacao;

try {
  classificacao = JSON.parse(conteudo);
} catch (error) {
  throw new Error(
    "A IA retornou um JSON inválido: " + error.message
  );
}

const categorias = [
  "cobranca",
  "suporte_tecnico",
  "duvida_produto",
  "cancelamento",
  "entrega_pedido",
  "elogio",
  "outros"
];

const urgencias = ["alta", "media", "baixa"];

const sentimentos = ["positivo", "neutro", "negativo"];

if (!categorias.includes(classificacao.categoria)) {
  throw new Error("Categoria inválida.");
}

if (!urgencias.includes(classificacao.urgencia)) {
  throw new Error("Urgência inválida.");
}

if (!sentimentos.includes(classificacao.sentimento)) {
  throw new Error("Sentimento inválido.");
}

return [
  {
    json: classificacao
  }
];
